get_shopping_cart.code:
final response = await client.shoppingCart.getShoppingCart();
final shoppingCart = (response.map as Map)['shopping_cart'] as Map;
print(shoppingCart['cart_page']);
print(shoppingCart['flying_cart']);

patch_shopping_cart.code:
final response = await client.shoppingCart.patchShoppingCart({
  'shopping_cart': {
    'cart_page': {'show_product_thumbnail': true},
    'flying_cart': {'save_cart': true},
  },
});
final shoppingCart = (response.map as Map)['shopping_cart'] as Map;
print(shoppingCart['cart_page']);
print(shoppingCart['flying_cart']);

